CREATE TABLE commercial_pricing_versions(id uuid PRIMARY KEY,boq_revision_id uuid NOT NULL REFERENCES boq_revisions(id),version integer NOT NULL CHECK(version>0),number text UNIQUE NOT NULL,snapshot jsonb NOT NULL,fingerprint text NOT NULL,request_key uuid UNIQUE NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(boq_revision_id,version));
CREATE TABLE quotation_versions(id uuid PRIMARY KEY,pricing_id uuid NOT NULL REFERENCES commercial_pricing_versions(id),boq_revision_id uuid NOT NULL REFERENCES boq_revisions(id),version integer NOT NULL CHECK(version>0),number text UNIQUE NOT NULL,snapshot jsonb NOT NULL,fingerprint text NOT NULL,request_key uuid UNIQUE NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(boq_revision_id,version));
CREATE TRIGGER immutable_commercial_pricing BEFORE UPDATE OR DELETE ON commercial_pricing_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_quotation BEFORE UPDATE OR DELETE ON quotation_versions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
